action.command:
cd /workspace; su - ddevuser -c 'cd /workspace && ddev exec php -r "
require \"vendor/autoload.php\";
\$c = require \"config/web.config.php\";
\$l = Dsl\\App\\Tools\\LdapUtility::getInstance();
echo \"connect=\" . var_export(\$l->connect(), true) . PHP_EOL;
echo \"bind=\" . var_export(\$l->bind(), true) . PHP_EOL;
echo \"search=\" . var_export(\$l->search(null, \"(objectClass=inetOrgPerson)\"), true) . PHP_EOL;
\$e = \$l->getEntries();
echo \"entries=\" . count(\$e) . PHP_EOL;
\$l->disconnect();
"' 2>&1 | tail -20

